  // ---------- MODEL LOADING ----------
  Future<void> _initModel() async {
    if (_interpreter != null) return;
    final tempDir = await getTemporaryDirectory();
    final modelPath = '${tempDir.path}/command_model.tflite';
    final modelFile = File(modelPath);
    if (!await modelFile.exists()) {
      final byteData = await rootBundle.load('assets/command_model.tflite');
      await modelFile.writeAsBytes(byteData.buffer.asUint8List());
    }
    _interpreter = await Interpreter.fromFile(modelFile);
    print("CommandService: Model loaded. Input shape: ${_interpreter!.getInputTensor(0).shape}");

    final labelsData = await rootBundle.loadString('assets/labels.txt');
    _labels = labelsData.split('\n').where((l) => l.isNotEmpty).toList();
    print("CommandService: Labels: $_labels");
  }

  // ---------- PUBLIC API ----------
  Future<void> startCommandListening({required Function(String) onCommandDetected}) async {
    if (_isListening) return;
    await _initModel();
    _onCommandDetected = onCommandDetected;
    _isListening = true;

    final hasPermission = await Permission.microphone.request().isGranted;
    if (!hasPermission) {
      print("CommandService: No microphone permission");
      return;
    }

    print("CommandService: Recording $recordSec second(s)...");

    try {
      final stream = await _audioRecorder.startStream(const RecordConfig(
        encoder: AudioEncoder.pcm16bits,
        sampleRate: sampleRate,
        numChannels: 1,
      ));

      final List<Uint8List> chunks = [];
      int totalBytes = 0;
      final completer = Completer<Uint8List>();

      _audioStreamSubscription = stream.listen((chunk) {
        if (!_isListening) return;
        chunks.add(chunk);
        totalBytes += chunk.length;
        if (totalBytes >= targetBytes) {
          _audioRecorder.stop();
          final allBytes = Uint8List(targetBytes);
          int offset = 0;
          for (var c in chunks) {
            final copyLen = (targetBytes - offset) < c.length ? (targetBytes - offset) : c.length;
            allBytes.setRange(offset, offset + copyLen, c.sublist(0, copyLen));
            offset += copyLen;
            if (offset >= targetBytes) break;
          }
          completer.complete(allBytes);
        }
      });

      final audioBytes = await completer.future;
      await _audioStreamSubscription?.cancel();
      await _audioRecorder.stop();

      // Convert bytes to float32 samples (range -1..1)
      final totalSamples = audioBytes.length ~/ 2;
      if (totalSamples != expectedSamples) {
        print("Warning: recorded ${totalSamples} samples, expected ${expectedSamples}");
      }
      final audioFloat = Float32List(totalSamples);
      for (int i = 0; i < totalSamples; i++) {
        final int sample = (audioBytes[i * 2] | (audioBytes[i * 2 + 1] << 8)).toSigned(16);
        audioFloat[i] = sample / 32768.0;
      }

      // Use exactly the recorded audio (1 second window)
      final window = audioFloat;

      // Compute mel spectrogram (exactly as in Colab)
      final melSpec = _computeMelSpectrogram(window);
      final input = melSpec.reshape([1, nMels, nTimeFrames, 1]);

      final output = List.filled(_labels.length, 0.0).reshape([1, _labels.length]);
      _interpreter!.run(input, output);
      final confidences = output[0] as List<double>;

      print("🔍 Raw confidences:");
      for (int i = 0; i < _labels.length; i++) {
        print("  ${_labels[i]}: ${confidences[i].toStringAsFixed(4)}");
      }

      // Find best command above threshold
      String? bestCommand;
      double bestConf = 0.0;
      for (int i = 0; i < confidences.length; i++) {
        final label = _labels[i];
        final conf = confidences[i];
        final thresh = thresholds[label] ?? 0.45;
        if (conf >= thresh && conf > bestConf && label != "background_noise_augmented") {
          bestCommand = label;
          bestConf = conf;
        }
      }

      if (bestCommand != null) {
        print("🎯 COMMAND DETECTED: $bestCommand (${(bestConf*100).toStringAsFixed(1)}%)");
        _onCommandDetected?.call(bestCommand);
      } else {
        print("CommandService: No command detected");
      }
    } catch (e, stack) {
      print("CommandService: Error: $e");
      print(stack);
    } finally {
      _isListening = false;
      await _audioStreamSubscription?.cancel();
      await _audioRecorder.stop();
    }
  }

  Future<void> stopCommandListening() async {
    _isListening = false;
    await _audioStreamSubscription?.cancel();
    await _audioRecorder.stop();
  }

  // ---------- FEATURE EXTRACTION (exact match to Colab) ----------
  Float32List _computeMelSpectrogram(Float32List audio) {
    final powerSpec = _stftPowerSpectrogram(audio);
    final nTime = powerSpec.length;
    final nFreqBins = nFft ~/ 2 + 1;

    // Apply mel filterbank
    final mel = List.generate(nMels, (_) => List.filled(nTime, 0.0));
    for (int t = 0; t < nTime; t++) {
      for (int m = 0; m < nMels; m++) {
        double sum = 0.0;
        for (int f = 0; f < nFreqBins; f++) {
          sum += _melFilterbank[m][f] * powerSpec[t][f];
        }
        mel[m][t] = sum;
      }
    }

    // Convert to dB (librosa.power_to_db)
    final melDb = List.generate(nMels, (_) => List.filled(nTime, 0.0));
    for (int m = 0; m < nMels; m++) {
      for (int t = 0; t < nTime; t++) {
        double val = math.max(mel[m][t], 1e-10);
        melDb[m][t] = 10.0 * math.log(val) / math.ln10;
      }
    }

    // Global min-max normalization to [0,1]
    double minVal = melDb[0][0], maxVal = melDb[0][0];
    for (int m = 0; m < nMels; m++) {
      for (int t = 0; t < nTime; t++) {
        if (melDb[m][t] < minVal) minVal = melDb[m][t];
        if (melDb[m][t] > maxVal) maxVal = melDb[m][t];
      }
    }
    final range = maxVal - minVal;
    final norm = List.generate(nMels, (_) => List.filled(nTime, 0.0));
    for (int m = 0; m < nMels; m++) {
      for (int t = 0; t < nTime; t++) {
        norm[m][t] = (melDb[m][t] - minVal) / (range + 1e-8);
      }
    }

    // Pad or trim to exactly nTimeFrames (43)
    final finalSpec = List.generate(nMels, (_) => List.filled(nTimeFrames, 0.0));
    for (int m = 0; m < nMels; m++) {
      for (int t = 0; t < nTimeFrames; t++) {
        if (t < nTime) finalSpec[m][t] = norm[m][t];
        else finalSpec[m][t] = 0.0;
      }
    }

    // Flatten to Float32List
    final flat = Float32List(nMels * nTimeFrames);
    int idx = 0;
    for (int m = 0; m < nMels; m++) {
      for (int t = 0; t < nTimeFrames; t++) {
        flat[idx++] = finalSpec[m][t].toDouble();
      }
    }
    return flat;
  }

  List<List<double>> _stftPowerSpectrogram(Float32List signal) {
    final frames = <List<double>>[];
    for (int start = 0; start + nFft <= signal.length; start += hopLength) {
      final frame = signal.sublist(start, start + nFft);
      // Hann window
      for (int i = 0; i < nFft; i++) {
        frame[i] *= 0.5 * (1 - math.cos(2 * math.pi * i / (nFft - 1)));
      }
      final complex = _fft(frame.map((x) => Complex(x, 0)).toList());
      final power = List<double>.generate(nFft ~/ 2 + 1, (i) {
        final c = complex[i];
        return c.real * c.real + c.imag * c.imag;
      });
      frames.add(power);
    }
    return frames;
  }

  List<Complex> _fft(List<Complex> x) {
    final n = x.length;
    if (n <= 1) return x;
    int j = 0;
    for (int i = 0; i < n - 1; i++) {
      if (i < j) {
        final tmp = x[i];
        x[i] = x[j];
        x[j] = tmp;
      }
      int k = n >> 1;
      while (k <= j) {
        j -= k;
        k >>= 1;
      }
      j += k;
    }
    for (int len = 2; len <= n; len <<= 1) {
      final angle = -2 * math.pi / len;
      final wlen = Complex(math.cos(angle), math.sin(angle));
      for (int i = 0; i < n; i += len) {
        Complex w = Complex(1, 0);
        for (int j = 0; j < len ~/ 2; j++) {
          final u = x[i + j];
          final v = x[i + j + len ~/ 2] * w;
          x[i + j] = u + v;
          x[i + j + len ~/ 2] = u - v;
          w = w * wlen;
        }
      }
    }
    return x;
  }
}

class Complex {
  double real, imag;
  Complex(this.real, this.imag);
  Complex operator +(Complex other) => Complex(real + other.real, imag + other.imag);
  Complex operator -(Complex other) => Complex(real - other.real, imag - other.imag);
  Complex operator *(Complex other) => Complex(
        real * other.real - imag * other.imag,
        real * other.imag + imag * other.real,
      );
}